insert into public.bko_clients(slug,name,original_name,website_url,website_original,website_verified,logo_local_path,logo_storage_path,logo_verified,logo_authorized,logo_source,logo_source_original,logo_status_original,verification_status,observations,sector,sector_source,description,sort_order,active,published,featured,relation_authorized,authorization_reference,logo_authorization_reference,original_row,logo_width,logo_height,logo_background) values('solucion-vial','Solución Vial','Solución Vial','https://solucionvial.cl/','https://solucionvial.cl/',true,'assets/clientes/solucion-vial.jpg','',true,true,'Logotipo entregado por el responsable del sitio (clientes/solucion vial.jpeg)','https://solucionvial.cl/','Logotipo entregado por el cliente','verified','Cliente agregado por instrucción del responsable del sitio (25-11-2026).','construccion','https://solucionvial.cl/','Señalización vial y demarcación.',360,true,true,true,true,'Instrucción del responsable del sitio, 25-11-2026: agregar Solución Vial al carrusel de clientes con su logotipo.','Instrucción del responsable del sitio, 25-11-2026, de mostrar el logotipo de Solución Vial.','https://solucionvial.cl/, nuevo cliente con su logo',720,818,'white') on conflict(slug) do nothing;

